update public.questions q set explanation=v.e from(values(0,'Wprowadzenie jasno nazywa temat i cel, dzięki czemu odbiorca rozumie kierunek całej wypowiedzi.'),(3,'Stałe połączenie „odnieść się do” wymaga dopełniacza: odnosimy się do opinii rozmówcy.'),(5,'„Następnie” porządkuje drugi etap wypowiedzi między początkiem argumentacji a końcowym wnioskiem.'),(6,'Konkretny przykład wzmacnia opinię, ponieważ pokazuje, jak ogólne twierdzenie działa w rzeczywistej sytuacji.'),(7,'Samoocena obejmuje poprawienie błędów, ocenę struktury i upewnienie się, że odpowiedź realizuje cel.'),(8,'Po przyimku „do” używamy dopełniacza: styl dostosowujemy do potrzeb konkretnego odbiorcy.'))v(p,e)where q.lesson_id='b1final-quiz'and q.position=v.p;
